from openpyxl import load_workbook
from openpyxl.styles import Alignment
import itertools

# Load the workbook
wb = load_workbook('input.xlsx')
data_sheet = wb['DATA']
combined_sheet = wb['combined']

# Define the reference column (Column H, index 7)
reference_col = 7

# Group rows by the reference column value
rows_by_reference = {}
for row in data_sheet.iter_rows(min_row=2, values_only=True):
    reference_value = row[reference_col]
    if reference_value not in rows_by_reference:
        rows_by_reference[reference_value] = []
    rows_by_reference[reference_value].append(row)

# Prepare the header for the combined sheet
header = [cell.value for cell in data_sheet[1]]
combined_sheet.append(header)

# Process each group
for group in rows_by_reference.values():
    # Extract the unique non-reference row
    unique_row = None
    for row in group:
        if unique_row is None:
            unique_row = row
        else:
            # For non-reference columns, sum the values (ignoring empty cells)
            for i in range(len(unique_row)):
                if i != reference_col:
                    if unique_row[i] is None:
                        unique_row[i] = 0
                    if row[i] is not None and row[i] != '':
                        unique_row[i] += row[i]
    # Apply formatting to the unique row
    for i, value in enumerate(unique_row):
        if i != reference_col:
            # Formatting for columns I:R (indices 8 to 17)
            if 8 <= i <= 17:
                # Convert to float, round to 2 decimals, and format
                if value is None or value == '':
                    formatted_value = ''
                else:
                    formatted_value = round(float(value), 2)
                    formatted_value = f"{formatted_value:.2f}".replace(",", "")
                # Set the value and formatting
                combined_sheet.cell(row=combined_sheet.max_row + 1, column=i + 1, value=formatted_value)
            else:
                # For other columns, just set the value
                combined_sheet.cell(row=combined_sheet.max_row + 1, column=i + 1, value=value)

# Save the workbook
wb.save('output.xlsx')
