from openpyxl import load_workbook
import re

def increment_urn(urn):
    # Extract the numeric part and the suffix
    match = re.match(r'^(\d+)([a-zA-Z]*)$', urn)
    if not match:
        return urn  # Not a valid URN format
    number, suffix = match.groups()
    number = int(number)

    # Convert suffix to a number
    def suffix_to_number(suffix):
        if not suffix:
            return 0
        return sum((1 << (ord(c) - ord('a') + 1)) for c in suffix)

    # Increment the number
    new_number = number + 1
    new_suffix = ''

    # Convert the new number to the suffix format
    def number_to_suffix(number):
        if number == 0:
            return ''
        suffix = ''
        while number > 0:
            number -= 1
            suffix = chr(97 + (number % 26)) + suffix
            number //= 26
        return suffix

    new_suffix = number_to_suffix(new_number)
    return f"{new_number}{new_suffix}"

def process_urns():
    # Load the workbook and the sheet
    wb = load_workbook('input.xlsx')
    ws = wb['Sheet1']

    # Find the last non-blank cell in column A
    last_non_blank_row = None
    for row in ws.iter_rows(min_col=1, max_col=1):
        for cell in row:
            if cell.value is not None and cell.value != '':
                last_non_blank_row = cell.row
                break
        if last_non_blank_row is not None:
            break

    # Iterate through the rows and process URNs
    for row in ws.iter_rows(min_row=1, max_col=1, max_row=ws.max_row):
        cell = row[0]
        if cell.value is None or cell.value == '':
            # Find the last non-blank cell above this cell
            for i in range(cell.row - 1, 0, -1):
                if ws[f'A{i}'].value is not None and ws[f'A{i}'].value != '':
                    last_non_blank = ws[f'A{i}'].value
                    break
            else:
                last_non_blank = None

            if last_non_blank is not None:
                # Generate the new URN
                new_urn = increment_urn(last_non_blank)
                cell.value = new_urn
            else:
                # If no non-blank cell found, leave it blank
                pass

    # Save the workbook
    wb.save('output.xlsx')

# Run the processing
process_urns()
