from openpyxl import load_workbook
from datetime import datetime, timedelta
import math

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Define the years range
years_range = range(2010, 2023)  # 2010 to 2022 inclusive

# Initialize the result row
result_row = [None] * 15  # 15 columns (including the year column)

# Function to calculate the number of days in a month
def days_in_month(year, month):
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        else:
            return 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

# Function to format the percentage value
def format_percentage(value):
    if value == 0:
        return 0
    elif value < 1e-9:
        return 0
    elif value < 1e-1:
        return round(value, 1)
    else:
        return round(value, 9)

# Iterate over each year in the range
for year in years_range:
    # Find the column index for the year
    year_col = None
    for col in range(1, 15):
        cell = ws.cell(row=4, column=col)
        if cell.value == year:
            year_col = col
            break
    if year_col is None:
        continue  # Skip if year not found

    # Initialize total shifts and night shifts for the year
    total_shifts = 0
    night_shifts = 0

    # Iterate over each month
    for month in range(1, 13):
        # Find the cell for the month
        month_cell = None
        for col in range(1, 15):
            cell = ws.cell(row=8, column=col)
            if cell.value == datetime(year=1, month=month, day=1).strftime('%b'):
                month_cell = col
                break
        if month_cell is None:
            continue  # Skip if month not found

        # Get the number of days in the month
        days = days_in_month(year, month)

        # Get the night shift count for the month
        night_shift_cell = ws.cell(row=9, column=month_cell)
        night_shifts += night_shift_cell.value if night_shift_cell.value is not None else 0

        # Calculate the total shifts for the month (assuming 1 shift per day)
        total_shifts += days

    # Calculate the percentage of night shifts
    if total_shifts == 0:
        percentage = 0
    else:
        percentage = night_shifts / total_shifts

    # Format the percentage
    formatted_percentage = format_percentage(percentage)

    # Write the formatted percentage to the result row
    result_row[year_col - 1] = formatted_percentage

# Write the result row to the worksheet
for col in range(1, 15):
    cell = ws.cell(row=11, column=col)
    cell.value = result_row[col - 1]

# Save the workbook
wb.save('output.xlsx')
